/** Return the on-the-wire length of an attribute value
 *
 * @param[in] vp to return the length of.
 * @return the length of the attribute.
 */
size_t fr_dhcpv6_option_len(fr_pair_t const *vp)
{
        switch (vp->vp_type) {
        case FR_TYPE_VARIABLE_SIZE:
#ifndef NDEBUG
                if (!vp->da->flags.extra &&
                    ((vp->da->flags.subtype == FLAG_ENCODE_DNS_LABEL) ||
                     (vp->da->flags.subtype == FLAG_ENCODE_PARTIAL_DNS_LABEL))) {
                        fr_assert_fail("DNS labels MUST be encoded/decoded with their own function, and not with generic 'string' functions");
                        return 0;
                }
#endif

                if (vp->da->flags.length) return vp->da->flags.length;  /* Variable type with fixed length */

                /*
                 *      Arrays get maxed at 2^16-1
                 */
                if (vp->da->flags.array && ((vp->vp_type == FR_TYPE_STRING) || (vp->vp_type == FR_TYPE_OCTETS))) {
                        if (vp->vp_length > 65535) return 65535;
                }

                return vp->vp_length;

        case FR_TYPE_DATE:
        case FR_TYPE_TIME_DELTA:
                if (vp->data.enumv->flags.length) return vp->data.enumv->flags.length;
                return sizeof(uint32_t);

        case FR_TYPE_STRUCTURAL:
                fr_assert_fail(NULL);
                return 0;

        default:
                return fr_dhcpv6_attr_sizes[vp->vp_type][0];
        }
}

static ssize_t fr_dhcpv6_ok_internal(uint8_t const *packet, uint8_t const *end, size_t max_attributes, int depth);

static ssize_t fr_dhcpv6_options_ok(uint8_t const *packet, uint8_t const *end, size_t max_attributes,
                                    bool allow_relay, int depth)
{
        size_t attributes;
        uint8_t const *p;

        attributes = 0;
        p = packet;

        while (p < end) {
                uint16_t len;

                if ((size_t)(end - p) < DHCPV6_OPT_HDR_LEN) {
                        fr_strerror_const("Not enough room for option header");
                        return -(p - packet);
                }

                len = DHCPV6_GET_OPTION_LEN(p);
                if ((size_t)(end - p) < (DHCPV6_OPT_HDR_LEN + len)) {
                        fr_strerror_const("Option length overflows the packet");
                        return -(p - packet);
                }

                attributes++;
                if (attributes > (size_t) max_attributes) {
                        fr_strerror_const("Too many attributes");
                        return -(p - packet);
                }

                /*
                 *      Recurse into the Relay-Message attribute, but
                 *      only if the outer packet was a relayed message.
                 */
                if (allow_relay && (p[0] == 0) && (p[1] == attr_relay_message->attr)) {
                        ssize_t child;

                        /*
                         *      Recurse to check the encapsulated packet.
                         */
                        child = fr_dhcpv6_ok_internal(p + 4, p + 4 + len, max_attributes - attributes, depth + 1);
                        if (child <= 0) return -((p + 4) - packet) + child;

                        attributes += child;
                }

                p += DHCPV6_OPT_HDR_LEN + len;
        }

        return attributes;
}

static ssize_t fr_dhcpv6_ok_internal(uint8_t const *packet, uint8_t const *end, size_t max_attributes, int depth)
{
        uint8_t const   *p;
        ssize_t         attributes;
        bool            allow_relay;
        size_t          packet_len = end - packet;

        if (end == packet) {
                fr_strerror_const("Packet is empty");
                return 0;
        }

        if (depth > DHCPV6_MAX_RELAY_NESTING) {
                fr_strerror_const("Too many layers forwarded packets");
                return 0;
        }

        switch (packet[0]) {
        case FR_DHCPV6_RELAY_FORWARD:
        case FR_DHCPV6_RELAY_REPLY:
